WITH ranked AS (
  SELECT ticket_id, status,
         ROW_NUMBER() OVER (PARTITION BY ... ORDER BY ...) AS rn
  FROM ticket_events
)
SELECT ticket_id, status FROM ranked WHERE rn = 1 ORDER BY ticket_id;

WITH months AS (
  SELECT strftime('%Y-%m', sold_at) AS month, SUM(amount) AS revenue
  FROM sales GROUP BY 1
)
SELECT month, revenue, ...
FROM months ORDER BY month;

WITH RECURSIVE tree(id, depth) AS (
  SELECT id, 0 FROM employees WHERE manager_id IS NULL
  UNION ALL
  SELECT e.id, ... FROM employees e JOIN tree ON ...
)
SELECT id, depth FROM tree ORDER BY id;
